package com.voice.studio;
import java.io.*;
public class PcmFormatsTest {
 static void test(int encoding,int width)throws Exception{File path=File.createTempFile("voices-format-",".wav");try{try(RandomAccessFile out=new RandomAccessFile(path,"rw")){out.writeBytes("RIFF");PcmAudio.writeLE(out,36+width*4,4);out.writeBytes("WAVEfmt ");PcmAudio.writeLE(out,16,4);PcmAudio.writeLE(out,encoding,2);PcmAudio.writeLE(out,2,2);PcmAudio.writeLE(out,24000,4);PcmAudio.writeLE(out,24000*width*2,4);PcmAudio.writeLE(out,width*2,2);PcmAudio.writeLE(out,width*8,2);out.writeBytes("data");PcmAudio.writeLE(out,width*4,4);for(double sample:new double[]{.5,-.5,-.25,.75})PcmAudio.writeLE(out,encoding==3?Float.floatToIntBits((float)sample):(long)(sample*Math.pow(2,width*8-1)),width);}try(PcmAudio.Reader reader=new PcmAudio.Reader(path)){float[] mono=reader.read(0,reader.seconds());float[][] stereo=reader.stereo(0,reader.seconds());if(mono.length!=2||Math.abs(mono[0])>1e-6||Math.abs(mono[1]-.25)>1e-6||Math.abs(stereo[0][0]-.5)>1e-6||Math.abs(stereo[1][0]+.5)>1e-6)throw new AssertionError("PCM format "+encoding+" / "+width);}}finally{path.delete();}}
 public static void main(String[] args)throws Exception{test(1,2);test(1,3);test(1,4);test(3,4);File path=File.createTempFile("voices-stereo-",".wav");try{try(PcmAudio.Writer writer=new PcmAudio.Writer(path,44100,2)){writer.write(new float[]{.5f,-.5f});writer.silence(1);}try(PcmAudio.Reader reader=new PcmAudio.Reader(path)){if(reader.channels!=2||reader.frames!=44101)throw new AssertionError("Stereo writer frame alignment");}}finally{path.delete();}System.out.println("PCM16/24/32, float32, signed stereo, mono downmix and stereo silence checks passed.");}
}
